css:
.pokwit { font-family: Arial, Helvetica, sans-serif; font-size: 8.5px; color:#111; width:100%; line-height:1.25; }
table.head { width:100%; border-collapse:collapse; border-bottom:1.5px solid #000; margin-bottom:4px; }
table.head td { vertical-align:top; padding-bottom:3px; }
.brand img.logo { height:30px; margin-bottom:2px; }
.brand .iss { font-size:11px; margin-top:1px; }
.brand .iss b { font-size:12px; }
td.meta { text-align:right; }
td.meta .title { font-weight:bold; font-size:9.5px; }
table.kv { width:100%; border-collapse:collapse; margin:2px 0; }
table.kv td { padding:1px 2px; vertical-align:top; }
table.kv td.l { font-weight:bold; width:62px; white-space:nowrap; }
.block { margin:2px 0; }
.block .l { font-weight:bold; }
.warranty { margin-top:4px; font-size:7.5px; border:1px solid #000; padding:3px; }
table.sign { width:100%; border-collapse:collapse; margin-top:18px; }
table.sign td { width:50%; text-align:center; font-size:7.5px; padding:0 8px; }
table.sign .line { border-top:1px solid #000; padding-top:2px; }
.rodo { margin-top:6px; font-size:6.5px; color:#444; text-align:justify; border-top:1px dashed #999; padding-top:2px; }
@media print { @page { size: 105mm 148mm; margin: 4mm; } }
